    const { loadBrowserSession, saveBrowserSession } =
      await import('../../utils/browser-session');
    vi.mocked(loadBrowserSession).mockReturnValueOnce(null); // no session first call
    vi.mocked(loadBrowserSession).mockReturnValue({
      // session exists after launch
      id: 'new-session',
      cdpUrl: 'wss://new',
      createdAt: '2025-01-01T00:00:00Z',
    });

    mockClient.browser.mockResolvedValue({
      success: true,
      id: 'new-session',
      cdpUrl: 'wss://new',
    });

    await handleBrowserQuickExecute({ code: 'open https://example.com' });

    expect(mockClient.browser).toHaveBeenCalledTimes(1);
    expect(mockClient.browser).toHaveBeenCalledWith(
      expect.objectContaining({ integration: 'cli' })
    );
    expect(saveBrowserSession).toHaveBeenCalledWith(
      expect.objectContaining({ id: 'new-session' })
    );
  });

  it('quick execute auto-launch passes origin cli with profile', async () => {
    const { loadBrowserSession } = await import('../../utils/browser-session');
    vi.mocked(loadBrowserSession).mockReturnValueOnce(null);
    vi.mocked(loadBrowserSession).mockReturnValue({
      id: 'new-session',
      cdpUrl: 'wss://new',
      createdAt: '2025-01-01T00:00:00Z',
    });

    mockClient.browser.mockResolvedValue({
      success: true,
      id: 'new-session',
      cdpUrl: 'wss://new',
    });

    await handleBrowserQuickExecute({
      code: 'open https://example.com',
      profile: 'dev',
      saveChanges: false,
    });

    expect(mockClient.browser).toHaveBeenCalledWith(
      expect.objectContaining({
        integration: 'cli',
        profile: { name: 'dev', saveChanges: false },
      })
    );
  });

  it('quick execute retries with new session on 403 Forbidden', async () => {
    const { clearBrowserSession, saveBrowserSession } =
      await import('../../utils/browser-session');

    // First execute call fails with 403 (stale cached session)
    const forbiddenError = Object.assign(new Error('Forbidden'), {
      status: 403,
    });
    mockClient.browserExecute
      .mockRejectedValueOnce(forbiddenError)
      .mockResolvedValueOnce({
        success: true,
        stdout: 'page loaded',
      });

    // Launch new session succeeds
    mockClient.browser.mockResolvedValue({
      success: true,
      id: 'fresh-session',
      cdpUrl: 'wss://fresh',
    });

    await handleBrowserQuickExecute({ code: 'open https://example.com' });

    expect(clearBrowserSession).toHaveBeenCalled();
    expect(mockClient.browser).toHaveBeenCalledTimes(1);
    expect(saveBrowserSession).toHaveBeenCalledWith(
      expect.objectContaining({ id: 'fresh-session' })
    );
    expect(mockClient.browserExecute).toHaveBeenCalledTimes(2);
  });

  it('quick execute retries with new session on 410 Gone', async () => {
    const { clearBrowserSession } = await import('../../utils/browser-session');

    const goneError = Object.assign(new Error('Gone'), { status: 410 });
    mockClient.browserExecute
      .mockRejectedValueOnce(goneError)
      .mockResolvedValueOnce({
        success: true,
        stdout: 'page loaded',
      });

    mockClient.browser.mockResolvedValue({
      success: true,
      id: 'fresh-session',
      cdpUrl: 'wss://fresh',
    });

    await handleBrowserQuickExecute({ code: 'open https://example.com' });

    expect(clearBrowserSession).toHaveBeenCalled();
    expect(mockClient.browser).toHaveBeenCalledTimes(1);
    expect(mockClient.browserExecute).toHaveBeenCalledTimes(2);
  });

  it('quick execute retries on "session destroyed" error message', async () => {
    const { clearBrowserSession } = await import('../../utils/browser-session');

    mockClient.browserExecute
      .mockRejectedValueOnce(new Error('session has been destroyed'))
      .mockResolvedValueOnce({
        success: true,
        stdout: 'ok',
      });

    mockClient.browser.mockResolvedValue({
      success: true,
      id: 'fresh-session',
      cdpUrl: 'wss://fresh',
    });

    await handleBrowserQuickExecute({ code: 'open https://example.com' });

    expect(clearBrowserSession).toHaveBeenCalled();
    expect(mockClient.browserExecute).toHaveBeenCalledTimes(2);
  });

  it('quick execute exits on non-session errors without retry', async () => {
    mockClient.browserExecute.mockRejectedValueOnce(
      new Error('Network timeout')
    );

    await handleBrowserQuickExecute({ code: 'open https://example.com' });

    expect(mockClient.browser).not.toHaveBeenCalled();
    expect(mockExit).toHaveBeenCalledWith(1);
  });
});

# Testing Guide

This directory contains tests for the Firecrawl CLI commands. Tests use Vitest and mock the Firecrawl client to avoid making real API calls.

## Running Tests

```bash
# Run tests once
pnpm test:run

# Run tests in watch mode
pnpm test:watch

# Run tests with UI
pnpm test:ui
```

## Test Structure

- `commands/` - Tests for command implementations
- `utils/` - Test utilities and helpers

## Writing Tests

### Key Principles

1. **No Real API Calls**: All tests mock the Firecrawl client or fetch API
2. **Verify API Call Generation**: Tests ensure commands generate correct API call parameters
3. **Verify Response Handling**: Tests ensure commands properly handle success and error responses
4. **Type Safety**: TypeScript ensures type correctness

### Example Test Pattern

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { executeScrape } from '../../commands/scrape';
import { getClient } from '../../utils/client';
import { setupTest, teardownTest } from '../utils/mock-client';

// Mock the client module
vi.mock('../../utils/client', async () => {
  const actual = await vi.importActual('../../utils/client');
  return {
    ...actual,
    getClient: vi.fn(),
  };
});

describe('executeScrape', () => {
  let mockClient: any;

  beforeEach(() => {
    setupTest();
    mockClient = { scrape: vi.fn() };
    vi.mocked(getClient).mockReturnValue(mockClient);
  });

  it('should call scrape with correct parameters', async () => {
    mockClient.scrape.mockResolvedValue({ markdown: '# Test' });

    await executeScrape({ url: 'https://example.com' });

    expect(mockClient.scrape).toHaveBeenCalledWith('https://example.com', {
      formats: ['markdown'],
    });
  });
});
```

## Test Utilities

### `setupTest()` / `teardownTest()`

Resets client and config state between tests. Always use these in `beforeEach`/`afterEach`.

### Mocking Patterns

- **Client methods**: Mock `getClient()` to return a mock client with stubbed methods
- **Fetch API**: Mock `global.fetch` for commands that use fetch directly
- **Config**: Use `initializeConfig()` to set test configuration

## What to Test

1. **API Call Parameters**: Verify commands pass correct parameters to the client
2. **Response Handling**: Test success and error response handling
3. **Option Parsing**: Ensure CLI options are correctly converted to API parameters
4. **Edge Cases**: Test with missing/optional parameters, null values, etc.

import { describe, expect, it } from 'vitest';
import {
  buildCreateBody,
  hasCreateFlagPayload,
  hasUpdateFlagPayload,
} from '../../commands/monitor';

describe('monitor command helpers', () => {
  describe('buildCreateBody', () => {
    it('includes a goal when creating a monitor from flags', () => {
      expect(
        buildCreateBody({
          name: 'Pricing',
          goal: 'Track plan price and feature changes',
          scheduleText: 'every 30 minutes',
          timezone: 'UTC',
          urls: ['https://example.com/pricing'],
        })
      ).toEqual({
        name: 'Pricing',
        goal: 'Track plan price and feature changes',
        schedule: {
          text: 'every 30 minutes',
          timezone: 'UTC',
        },
        targets: [
          {
            type: 'scrape',
            urls: ['https://example.com/pricing'],
          },
        ],
      });
    });

    it('builds a search target from queries and search options', () => {
      expect(
        buildCreateBody({
          name: 'LLM releases',
          goal: 'Notify me about major new LLM model releases',
          scheduleText: 'every 2 hours',
          timezone: 'UTC',
          queries: ['new LLM release', 'frontier model launch'],
          searchWindow: '24h',
          maxResults: 10,
          includeDomains: ['openai.com'],
          excludeDomains: ['reddit.com'],
        })
      ).toEqual({
        name: 'LLM releases',
        goal: 'Notify me about major new LLM model releases',
        schedule: {
          text: 'every 2 hours',
          timezone: 'UTC',
        },
        targets: [
          {
            type: 'search',
            queries: ['new LLM release', 'frontier model launch'],
            searchWindow: '24h',
            maxResults: 10,
            includeDomains: ['openai.com'],
            excludeDomains: ['reddit.com'],
          },
        ],
      });
    });

    it('requires a goal for web monitors', () => {
      expect(() =>
        buildCreateBody({
          name: 'No goal',
          scheduleText: 'hourly',
          queries: ['something'],
        })
      ).toThrow(/goal is required for web monitors/);
    });

    it('supports the simple page plus goal path', () => {
      expect(
        buildCreateBody({
          name: 'Docs',
          goal: 'Tell me when the changelog adds a new release',
          scheduleText: 'hourly',
          page: 'https://example.com/changelog',
        })
      ).toMatchObject({
        name: 'Docs',
        goal: 'Tell me when the changelog adds a new release',
        targets: [
          {
            type: 'scrape',
            urls: ['https://example.com/changelog'],
          },
        ],
      });
    });
  });

  describe('stdin payload policy', () => {
    it('does not implicitly read stdin when create flags can build a payload', () => {
      expect(
        hasCreateFlagPayload({
          name: 'LLM releases',
          goal: 'Track new model launches',
          schedule: 'hourly',
          queries: ['OpenAI release'],
        })
      ).toBe(true);
    });

    it('still allows implicit stdin for create when no payload flags are present', () => {
      expect(hasCreateFlagPayload({ timezone: 'UTC' })).toBe(false);
    });

    it('does not implicitly read stdin when update flags can build a payload', () => {
      expect(hasUpdateFlagPayload({ state: 'paused' })).toBe(true);
    });

    it('still allows implicit stdin for update when no update flags are present', () => {
      expect(hasUpdateFlagPayload({})).toBe(false);
    });
  });
});

# JSON-mode change tracking (structured per-field diffs)

Reference for structured change tracking. Read from [SKILL.md](SKILL.md) when the user cares about specific structured fields (price, headline, in-stock flag, items in a list) rather than whole-page markdown diffs.

By default monitors diff each page's markdown and return a unified text diff. JSON-mode change tracking returns keyed per-field diffs instead — e.g. `plans[0].price: "$19/mo" → "$24/mo"` — which drop straight into a Slack message, CI step, or internal tool. The CLI flags don't cover this — pass a JSON body via positional file or piped stdin:

```bash
cat > pricing-monitor.json <<'EOF'
{
  "name": "Pricing watch",
  "goal": "Alert when plan prices or headline features change.",
  "schedule": { "text": "hourly", "timezone": "UTC" },
  "targets": [{
    "type": "scrape",
    "urls": ["https://example.com/pricing"],
    "scrapeOptions": {
      "formats": [{
        "type": "changeTracking",
        "modes": ["json"],
        "prompt": "Extract pricing tiers and headline features for each plan.",
        "schema": {
          "type": "object",
          "properties": {
            "plans": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "name":     { "type": "string" },
                  "price":    { "type": "string" },
                  "features": { "type": "array", "items": { "type": "string" } }
                }
              }
            }
          }
        }
      }]
    }
  }]
}
EOF
firecrawl monitor create pricing-monitor.json
# or: cat pricing-monitor.json | firecrawl monitor create
```

Each changed page in the check response then carries a per-field diff plus a snapshot of the current full extraction:

```json
{
  "url": "https://example.com/pricing",
  "status": "changed",
  "diff": {
    "json": {
      "plans[0].price": { "previous": "$19/mo", "current": "$24/mo" },
      "plans[1].features[2]": {
        "previous": "10 GB storage",
        "current": "25 GB storage"
      }
    }
  },
  "snapshot": {
    "json": {
      "plans": [
        { "name": "Pro", "price": "$49/mo", "features": ["25 GB storage"] }
      ]
    }
  }
}
```

Use `modes: ["json", "git-diff"]` for **mixed mode** — you get both `diff.json` (per-field) and `diff.text` (markdown sidecar), and the page is marked `changed` whenever either surface changed. For markdown-only monitors, `diff.text` holds the unified diff and `diff.json` is a `parse-diff` AST (`{ files: [...] }`); there is no `snapshot`.

/**
 * Repos to pull skills from during install.
 *
 * - firecrawl/cli: core CLI skills bundled with this repo
 * - firecrawl/skills: additional "build" skills for working with Firecrawl
 *
 * Workflow skills live in a separate installable repo:
 *
 * - firecrawl/firecrawl-workflows: outcome-focused Firecrawl workflow skills
 *
 * `firecrawl init` installs core CLI skills and workflow skills.
 * `firecrawl setup skills` (alias `setup core`) installs core CLI skills,
 * `firecrawl setup build` installs build skills, and
 * `firecrawl setup workflows` installs workflow skills.
 */
export const SKILL_REPOS = ['firecrawl/cli', 'firecrawl/skills'] as const;

export const WORKFLOW_SKILL_REPOS = ['firecrawl/firecrawl-workflows'] as const;

export const ALL_SKILL_REPOS = [
  ...SKILL_REPOS,
  ...WORKFLOW_SKILL_REPOS,
] as const;

/**
 * The skills catalog — the one promoted install source for every skill
 * family. `firecrawl init` installs from here so install volume accrues to
 * catalog counters on skills.sh.
 */
export const CATALOG_REPO = 'firecrawl/skills';

/**
 * Core skills, authored in firecrawl/cli and mirrored into the catalog under
 * skills/core/. Selection is name-based (`--skill`), so the catalog's
 * directory layout doesn't matter.
 */
export const CLI_SKILLS = [
  'firecrawl',
  'firecrawl-scrape',
  'firecrawl-search',
  'firecrawl-crawl',
  'firecrawl-map',
  'firecrawl-interact',
  'firecrawl-agent',
  'firecrawl-monitor',
  'firecrawl-parse',
  'firecrawl-download',
  // Index skills: teach the `firecrawl research` / `firecrawl developer`
  // CLI commands, so they ship with the CLI set.
  'firecrawl-research-index',
  'firecrawl-developer-index',
] as const;

/**
 * Build skills, authored in the firecrawl monorepo `skills/` and mirrored
 * into the catalog. App-integration guidance; not installed by `init`.
 */
export const BUILD_SKILLS = [
  'firecrawl-build',
  'firecrawl-build-onboarding',
  'firecrawl-build-scrape',
  'firecrawl-build-search',
  'firecrawl-build-interact',
